    private HttpRequest buildRequest(String method, String path,
            List<Map.Entry<String, String>> query, Map<String, String> headers,
            Map<String, String> cookies, byte[] body, String contentType,
            RequestOptions requestOptions) {
        URI uri = buildUri(path, query);
        HttpRequest.Builder builder = HttpRequest.newBuilder(uri)
                .timeout(requestOptions.timeout != null ? requestOptions.timeout : options.timeout);
        options.defaultHeaders.forEach((name, value) -> {
            if (name.equalsIgnoreCase("Idempotency-Key")) builder.setHeader(name, value);
            else builder.header(name, value);
        });
        headers.forEach((name, value) -> {
            if (name.equalsIgnoreCase("Idempotency-Key")) {
                if (!value.isBlank()) builder.setHeader(name, value);
            } else builder.header(name, value);
        });
        requestOptions.headers.forEach((name, value) -> {
            if (name.equalsIgnoreCase("Idempotency-Key")) builder.setHeader(name, value);
            else builder.header(name, value);
        });
        if (!cookies.isEmpty()) {
            String value = String.join("; ", cookies.entrySet().stream()
                    .map(item -> encode(item.getKey()) + "=" + encode(item.getValue())).toList());
            builder.header("Cookie", value);
        }
        // A value the caller set on a declared Idempotency-Key header parameter wins
        // over RequestOptions.idempotencyKey; either key is replayed by every attempt.
        if (requestOptions.hasIdempotencyKey() && headers.entrySet().stream().noneMatch(item ->
                item.getKey().equalsIgnoreCase("Idempotency-Key") && !item.getValue().isBlank()))
            builder.setHeader("Idempotency-Key", requestOptions.idempotencyKey);
        if (body != null && contentType != null) builder.header("Content-Type", contentType);
        HttpRequest.BodyPublisher publisher = body == null
                ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofByteArray(body);
        return builder.method(method, publisher).build();
    }

    private URI buildUri(String path, List<Map.Entry<String, String>> query) {
        String base = baseUri.toString().replaceAll("/+$", "") + "/" + path.replaceAll("^/+", "");
        if (query.isEmpty()) return URI.create(base);
        String separator = base.contains("?") ? "&" : "?";
        String value = String.join("&", query.stream()
                .map(item -> encode(item.getKey()) + "=" + encode(item.getValue())).toList());
        return URI.create(base + separator + value);
    }

    /** Fetch a Link-pagination target without allowing the call to leave this origin. */
    private CompletableFuture<ResponseData> sendLinkAsync(URI target, String operationId,
            RequestOptions requestOptions, boolean retryable, List<List<String>> security) {
        if (!sameOrigin(baseUri, target)) {
            throw new IllegalArgumentException("Cross-origin pagination link rejected: " + target);
        }
        Map<String, String> headers = new LinkedHashMap<>(requestOptions.headers);
        Map<String, String> cookies = new LinkedHashMap<>();
        applyAuthentication(new ArrayList<>(), headers, cookies, security, operationId);
        HttpRequest.Builder builder = HttpRequest.newBuilder(target).GET();
        Duration timeout = requestOptions.timeout == null ? options.timeout : requestOptions.timeout;
        if (timeout != null) builder.timeout(timeout);
        options.defaultHeaders.forEach(builder::header);
        headers.forEach(builder::header);
        if (!cookies.isEmpty()) builder.header("Cookie", String.join("; ",
                cookies.entrySet().stream().map(item -> item.getKey() + "=" + item.getValue()).toList()));
        return sendAsync(builder.build(), operationId, retryable, requestOptions);
    }

    private URI baseUri() { return baseUri; }

    private CompletableFuture<ResponseData> sendAsync(HttpRequest request, String operationId,
            boolean retryAllowed, RequestOptions requestOptions) {
        RetryCall call = retryCall(request, operationId, retryAllowed, requestOptions);
        return call.trace().settle(sendAttempt(call, 0, 1,
                attempt -> boundedBodyHandler(options.maxResponseBytes, operationId, attempt),
                (response, attempt) -> response.body()))
                .thenApply(response -> {
                    byte[] body = response.body();
                    return new ResponseData(response.statusCode(), response.headers().map(), body);
                });
    }

    /** Send without buffering: the 2xx body stays an open InputStream for incremental decoding. */
    private CompletableFuture<HttpResponse<InputStream>> sendStreamingAsync(HttpRequest request,
            String operationId, boolean retryAllowed, RequestOptions requestOptions) {
        RetryCall call = retryCall(request, operationId, retryAllowed, requestOptions);
        return StreamExchange.of(call.trace().settle(sendAttempt(call, 0, 1,
                attempt -> HttpResponse.BodyHandlers.ofInputStream(),
                (response, attempt) -> readBounded(response.body(), options.maxResponseBytes, operationId, attempt))));
    }

    /**
     * One call's retry plan: the endpoints its attempts may target, whether it may be
     * retried at all, the attempt limit, when it started (for retryBudget) and the trace
     * that reports it to the lifecycle hooks and the tracer.
     */
    private record RetryCall(String operationId, boolean retryAllowed, int maxRetries, List<URI> baseUris,
            List<HttpRequest> requests, long startedNanos, CallTrace trace) {}

    private static final String REDACTED = "[redacted]";

    /** Every configured credential value, redacted from hook contexts and spans. */
    private List<String> secretValues() {
        List<String> values = new ArrayList<>();
        for (String value : new String[] {options.apiKey, options.accessToken, options.password}) {
            if (value != null) values.add(value);
        }
        values.addAll(options.auth.values());
        return List.copyOf(values);
    }

    /**
     * The lower-cased header or query names that carry a credential: Authorization,
     * Proxy-Authorization and Cookie, and every API-key security scheme's name there.
     */
    private static Set<String> credentialNames(String location) {
        Set<String> names = new java.util.HashSet<>();
        if ("header".equals(location)) names.addAll(List.of("authorization", "proxy-authorization", "cookie"));
        for (AuthScheme scheme : AUTH_SCHEMES.values()) {
            if ("apiKey".equals(scheme.type) && location.equals(scheme.location) && scheme.name != null)
                names.add(scheme.name.toLowerCase(Locale.ROOT));
        }
        return names;
    }

    private static String redactSecrets(String text, List<String> secrets) {
        for (String secret : secrets) {
            if (secret != null && secret.length() >= 4) text = text.replace(secret, REDACTED);
        }
        return text;
    }

    /** An immutable copy of the request headers with every credential redacted. */
    private static Map<String, List<String>> redactedHeaders(HttpHeaders headers, List<String> secrets) {
        Set<String> hidden = credentialNames("header");
        Map<String, List<String>> result = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
        headers.map().forEach((name, values) -> result.put(name, values.stream()
                .map(value -> hidden.contains(name.toLowerCase(Locale.ROOT)) ? REDACTED : redactSecrets(value, secrets))
                .toList()));
        return Collections.unmodifiableMap(result);
    }

    /** The request URI with every API-key query value and configured credential redacted. */
    private static String redactedUrl(URI uri, List<String> secrets) {
        String text = uri.toString();
        String query = uri.getRawQuery();
        Set<String> hidden = credentialNames("query");
        int start = text.indexOf('?');
        if (query != null && start >= 0 && !hidden.isEmpty()) {
            List<String> pairs = new ArrayList<>();
            for (String pair : query.split("&", -1)) {
                String name = pair.split("=", 2)[0];
                String decoded;
                try { decoded = java.net.URLDecoder.decode(name, StandardCharsets.UTF_8); }
                catch (IllegalArgumentException malformed) { decoded = name; }
                pairs.add(hidden.contains(decoded.toLowerCase(Locale.ROOT)) ? name + "=" + REDACTED : pair);
            }
            int end = text.indexOf('#', start);
            text = text.substring(0, start + 1) + String.join("&", pairs) + (end < 0 ? "" : text.substring(end));
        }
        return redactSecrets(text, secrets);
    }

    /**
     * One call's lifecycle hooks and tracer span (tk omniwrap-55457rp5): every attempt
     * starts with beforeRequest and ends with exactly one of onRetry, afterResponse or
     * onError, and one span covers the call.
     */
    private static final class CallTrace {
        private final RequestHooks hooks;
        private final TraceSpan span;
        private final String operationId;
        private final String method;
        private final List<String> secrets;
        private final long startedNanos = System.nanoTime();
        private volatile int attempt;
        private volatile Integer status;
        private volatile String url = "";
        private volatile Map<String, List<String>> headers = Map.of();

        CallTrace(ClientOptions options, String operationId, String method, List<String> secrets) {
            this.hooks = options.hooks;
            this.operationId = operationId;
            this.method = method;
            this.secrets = secrets;
            this.span = options.tracer == null ? null
                    : options.tracer.startSpan(operationId, Map.of("http.request.method", method));
        }

        private HookContext context(Integer statusCode, Throwable error, Duration retryDelay) {
            return new HookContext(operationId, method, url, headers, attempt,
                    Duration.ofNanos(System.nanoTime() - startedNanos), statusCode, error, retryDelay);
        }

        void before(int number, HttpRequest request) {
            attempt = number;
            status = null;
            url = redactedUrl(request.uri(), secrets);
            headers = redactedHeaders(request.headers(), secrets);
            if (hooks != null) hooks.beforeRequest(context(null, null, null));
        }

        void retry(Integer statusCode, Throwable error, long waitMillis) {
            status = statusCode;
            if (hooks != null) hooks.onRetry(context(statusCode, error, Duration.ofMillis(waitMillis)));
        }

        /** Report how the call ended, then end the span, before the caller sees it. */
        <T> CompletableFuture<HttpResponse<T>> settle(CompletableFuture<HttpResponse<T>> call) {
            CompletableFuture<HttpResponse<T>> settled = new CompletableFuture<>();
            settled.whenComplete((ignored, error) -> { if (settled.isCancelled()) call.cancel(true); });
            call.whenComplete((response, rawError) -> {
                Throwable error = unwrap(rawError);
                try {
                    if (error == null) {
                        status = response.statusCode();
                        if (hooks != null && attempt > 0) hooks.afterResponse(context(status, null, null));
                    } else if (!(error instanceof CancellationException) && attempt > 0) {
                        if (error instanceof ApiException failure && failure.statusCode != 0) status = failure.statusCode;
                        if (hooks != null) hooks.onError(context(status, error, null));
                    }
                } catch (Throwable hookFailure) {
                    end();
                    if (response != null && response.body() instanceof InputStream body) {
                        try { body.close(); } catch (IOException ignored) { /* nothing reads it */ }
                    }
                    settled.completeExceptionally(hookFailure);
                    return;
                }
                end();
                if (error == null) settled.complete(response);
                else if (error instanceof CancellationException) settled.cancel(true);
                else settled.completeExceptionally(error);
            });
            return settled;
        }

        private void end() {
            if (span == null) return;
            Map<String, Object> attributes = new LinkedHashMap<>();
            attributes.put("http.request.resend_count", Math.max(attempt - 1, 0));
            if (status != null) attributes.put("http.response.status_code", status);
            span.end(Collections.unmodifiableMap(attributes));
        }
    }

    private RetryCall retryCall(HttpRequest request, String operationId, boolean retryAllowed,
            RequestOptions requestOptions) {
        int retries = requestOptions.maxRetries != null ? requestOptions.maxRetries : options.maxRetries;
        // An Idempotency-Key makes a non-idempotent operation safe to retry: the one
        // RequestOptions carries or a declared header parameter the caller set
        // (capability evidence needle: keep this call site on one line).
        boolean allowed = retryAllowed || requestOptions.hasIdempotencyKey() || isKeyedRequest(request);
        // Fallback endpoints serve idempotent operations only: a key makes a retry
        // safe on the same server, not on another one. The request is always built
        // from this client's base URI, which the fallbacks replace.
        List<URI> baseUris = new ArrayList<>(List.of(baseUri));
        List<HttpRequest> requests = new ArrayList<>(List.of(request));
        String primary = baseUri.toString().replaceAll("/+$", "");
        String target = request.uri().toString();
        if (retryAllowed && (target.startsWith(primary + "/") || target.startsWith(primary + "?"))) {
            for (URI fallback : options.fallbackBaseUris) {
                URI uri = URI.create(fallback.toString().replaceAll("/+$", "") + target.substring(primary.length()));
                baseUris.add(fallback);
                requests.add(HttpRequest.newBuilder(request, (name, value) -> true).uri(uri).build());
            }
        }
        return new RetryCall(operationId, allowed, retries, List.copyOf(baseUris), List.copyOf(requests),
                System.nanoTime(), new CallTrace(options, operationId, request.method(), secretValues()));
    }

    /** True when the request carries a non-blank Idempotency-Key, whichever parameter set it. */
    private static boolean isKeyedRequest(HttpRequest request) {
        return request.headers().allValues("Idempotency-Key").stream().anyMatch(value -> !value.isBlank());
    }

    /**
     * The future of one streaming exchange and of every stage derived from it
     * (V3-785). Cancelling the future an operation returns cancels the exchange
     * before its headers arrive, and a response that nothing will read is closed.
     */
    private static final class StreamExchange<T> extends CompletableFuture<T> {
        private final CompletableFuture<?> source;

        private StreamExchange(CompletableFuture<?> source) { this.source = source; }

        static <T> StreamExchange<T> of(CompletableFuture<T> exchange) {
            StreamExchange<T> result = new StreamExchange<>(exchange);
            exchange.whenComplete((value, error) -> {
                if (error == null) result.complete(value);
                else result.completeExceptionally(error);
            });
            return result;
        }

        @Override public <U> CompletableFuture<U> newIncompleteFuture() { return new StreamExchange<>(this); }

        @Override public boolean cancel(boolean mayInterruptIfRunning) {
            boolean cancelled = super.cancel(mayInterruptIfRunning);
            if (cancelled && !source.cancel(mayInterruptIfRunning) && source.isDone()
                    && !source.isCompletedExceptionally()
                    && source.join() instanceof HttpResponse<?> response
                    && response.body() instanceof InputStream body) {
                try { body.close(); } catch (IOException ignored) { /* nothing reads it */ }
            }
            return cancelled;
        }
    }

    /**
     * Prepare one streaming request (V3-785): refuse a StreamOptions bound out of
     * range before anything is sent, ask for the stream's media type unless the
     * caller set Accept, and seed Last-Event-ID for a server-sent-event stream
     * unless the caller set one. The request is built from this client's base
     * URI, so a seeded id stays within its origin.
     */
    private void prepareStream(Map<String, String> headers, RequestOptions requestOptions,
            String kind, String operationId) {
        StreamOptions stream = requestOptions.stream;
        if (stream.maxReconnects() < 0 || stream.maxReconnects() > StreamOptions.MAX_RECONNECTS) {
            throw new StreamingException("maxReconnects must be between 0 and 1000", operationId, kind,
                    stream.maxReconnects(), null);
        }
        Duration delay = stream.reconnectDelay();
        if (delay == null || delay.isNegative() || delay.compareTo(StreamOptions.MAX_RECONNECT_DELAY) > 0) {
            throw new StreamingException("reconnectDelay must be between 0 and 60 seconds", operationId, kind,
                    delay, null);
        }
        if (stream.maxLineLength() < 1 || stream.maxLineLength() > StreamOptions.MAX_LINE_LENGTH) {
            throw new StreamingException("maxLineLength must be between 1 and 100000000", operationId, kind,
                    stream.maxLineLength(), null);
        }
        boolean sse = "sse".equals(kind);
        if (!sse && stream.maxReconnects() != 0) {
            throw new StreamingException("NDJSON streams never resume, so maxReconnects must be 0", operationId,
                    kind, stream.maxReconnects(), null);
        }
        if (!containsHeader(headers, "Accept") && !containsHeader(requestOptions.headers, "Accept")
                && !containsHeader(options.defaultHeaders, "Accept")) {
            headers.put("Accept", sse ? "text/event-stream" : "application/x-ndjson");
        }
        if (sse && stream.lastEventId() != null && !containsHeader(headers, "Last-Event-ID")
                && !containsHeader(requestOptions.headers, "Last-Event-ID")
                && !containsHeader(options.defaultHeaders, "Last-Event-ID")) {
            headers.put("Last-Event-ID", stream.lastEventId());
        }
    }

    private static boolean containsHeader(Map<String, String> headers, String name) {
        for (String key : headers.keySet()) {
            if (key.equalsIgnoreCase(name)) return true;
        }
        return false;
    }

    /**
     * The replay of a server-sent-event request for one bounded resumption
     * (V3-785): the same request sent again through sendStreamingAsync, with its
     * Last-Event-ID replaced by the last event id seen. The id travels only when
     * the request targets this client's own origin.
     */
    private Function<String, CompletableFuture<HttpResponse<InputStream>>> streamReplay(HttpRequest request,
            String operationId, boolean retryAllowed, RequestOptions requestOptions) {
        boolean sameOrigin = sameOrigin(baseUri, request.uri());
        return lastEventId -> {
            HttpRequest.Builder replay = HttpRequest.newBuilder(request,
                    (name, value) -> !name.equalsIgnoreCase("Last-Event-ID"));
            if (sameOrigin && lastEventId != null && !lastEventId.isEmpty()) {
                replay.header("Last-Event-ID", lastEventId);
            }
            return sendStreamingAsync(replay.build(), operationId, retryAllowed, requestOptions);
        };
    }

    /** True when both URIs use http or https with the same scheme, host and effective port. */
    static boolean sameOrigin(URI left, URI right) {
        if (left == null || right == null || left.getScheme() == null || right.getScheme() == null) return false;
        String scheme = left.getScheme().toLowerCase(Locale.ROOT);
        if (!scheme.equals(right.getScheme().toLowerCase(Locale.ROOT))) return false;
        if (!scheme.equals("http") && !scheme.equals("https")) return false;
        if (left.getHost() == null || !left.getHost().equalsIgnoreCase(right.getHost())) return false;
        return effectivePort(left, scheme) == effectivePort(right, scheme);
    }

    private static int effectivePort(URI uri, String scheme) {
        if (uri.getPort() >= 0) return uri.getPort();
        return scheme.equals("https") ? 443 : 80;
    }

    /** Reads the body of a non-2xx response so it can travel on the ApiException. */
    private interface ErrorBodyReader<T> {
        byte[] read(HttpResponse<T> response, int attempt) throws IOException;
    }

    private <T> CompletableFuture<HttpResponse<T>> sendAttempt(RetryCall call, int endpoint, int attempt,
            IntFunction<HttpResponse.BodyHandler<T>> handlers, ErrorBodyReader<T> errorBodies) {
        HttpRequest request = call.requests().get(endpoint);
        String operationId = call.operationId();
        try { call.trace().before(attempt, request); }
        catch (Throwable failure) { return CompletableFuture.failedFuture(failure); }
        CompletableFuture<HttpResponse<T>> active = httpClient.sendAsync(request, handlers.apply(attempt));
        CompletableFuture<HttpResponse<T>> result = new CompletableFuture<>();
        result.whenComplete((ignored, error) -> {
            if (result.isCancelled()) active.cancel(true);
        });
        active.whenComplete((response, rawError) -> {
            // Nothing reads the stage whenComplete returns, so a throwable escaping
            // this callback, even an Error, ends the call instead of leaving it pending.
            try {
                if (result.isCancelled()) {
                    // A streamed response that nothing will read is closed with its connection.
                    if (response != null && response.body() instanceof InputStream body) {
                        try { body.close(); } catch (IOException ignored) { /* nothing reads it */ }
                    }
                    return;
                }
                Throwable error = unwrap(rawError);
                if (error != null) {
                    if (error instanceof ApiResponseTooLargeException) {
                        result.completeExceptionally(error);
                        return;
                    }
                    if (error instanceof CancellationException) {
                        result.cancel(true);
                        return;
                    }
                    ApiTransportException failure = error instanceof HttpTimeoutException
                            ? new ApiTimeoutException(operationId, attempt, request.timeout().orElse(options.timeout), error)
                            : new ApiTransportException(operationId, attempt, error);
                    // Connection failures and timeouts are retried only for retryable
                    // requests; the attempt budget is shared with status retries.
                    Long wait = call.retryAllowed() && attempt <= call.maxRetries() && isRetryableTransport(error)
                            ? retryWait(attempt, null, call.startedNanos()) : null;
                    if (!reportAttempt(call, endpoint, attempt, null, failure, wait, result)) return;
                    if (wait == null) {
                        result.completeExceptionally(failure);
                    } else {
                        // No response arrived, so an idempotent call moves to the next
                        // endpoint; the last one serves the remaining attempts.
                        int next = Math.min(endpoint + 1, call.requests().size() - 1);
                        transfer(delayedRetry(call, next, attempt, wait, handlers, errorBodies), result);
                    }
                    return;
                }
                int status = response.statusCode();
                if (status < 200 || status >= 300) {
                    // The server's verdict, else the status policy (capability evidence needle).
                    boolean retryable = shouldRetry(status, response.headers());
                    byte[] body;
                    try { body = errorBodies.read(response, attempt); }
                    catch (IOException | UncheckedIOException readError) { body = new byte[0]; }
                    catch (RuntimeException readError) { result.completeExceptionally(readError); return; }
                    // A server wait above maxRetryDelay, or one beyond retryBudget, surfaces
                    // the error at once (capability evidence needle: keep on one line).
                    Long wait = retryable && call.retryAllowed() && attempt <= call.maxRetries() ? retryWait(attempt, response.headers(), call.startedNanos()) : null;
                    if (!reportAttempt(call, endpoint, attempt, status, null, wait, result)) return;
                    if (wait != null) {
                        // A 5xx moves an idempotent call to the next endpoint; a 4xx retry,
                        // such as a 429, stays where it is.
                        int next = status >= 500 ? Math.min(endpoint + 1, call.requests().size() - 1) : endpoint;
                        transfer(delayedRetry(call, next, attempt, wait, handlers, errorBodies), result);
                    } else {
                        result.completeExceptionally(apiException(status, response.headers(), body,
                                operationId, attempt, retryable));
                    }
                    return;
                }
                if (!reportAttempt(call, endpoint, attempt, status, null, null, result)) {
                    // A streamed response that nothing will read is closed with its connection.
                    if (response.body() instanceof InputStream body) {
                        try { body.close(); } catch (IOException ignored) { /* nothing reads it */ }
                    }
                    return;
                }
                result.complete(response);
            } catch (Throwable failure) {
                result.completeExceptionally(failure);
            }
        });
        return result;
    }

    /**
     * Hand one attempt to the onAttempt listener, before any retry wait. A listener
     * failure, an Error such as a test assertion included, ends the call with it;
     * false then tells the caller to stop.
     */
    private boolean reportAttempt(RetryCall call, int endpoint, int attempt, Integer statusCode,
            ApiTransportException error, Long retryDelay, CompletableFuture<?> result) {
        if (retryDelay != null) {
            try { call.trace().retry(statusCode, error, retryDelay); }
            catch (Throwable failure) { result.completeExceptionally(failure); return false; }
        }
        Consumer<AttemptContext> listener = options.onAttempt;
        if (listener == null) return true;
        try {
            listener.accept(new AttemptContext(call.operationId(), attempt, call.baseUris().get(endpoint),
                    call.requests().get(endpoint).uri(), statusCode, error,
                    retryDelay == null ? null : Duration.ofMillis(retryDelay)));
            return true;
        } catch (Throwable failure) {
            result.completeExceptionally(failure);
            return false;
        }
    }

    private static HttpResponse.BodyHandler<byte[]> boundedBodyHandler(
            int maximumBytes, String operationId, int attempt) {
        return ignored -> HttpResponse.BodySubscribers.mapping(
                HttpResponse.BodySubscribers.ofInputStream(),
                stream -> {
                    try {
                        return readBounded(stream, maximumBytes, operationId, attempt);
                    } catch (IOException error) {
                        throw new UncheckedIOException(error);
                    }
                });
    }

    private static byte[] readBounded(InputStream stream, int maximumBytes,
            String operationId, int attempt) throws IOException {
        try (InputStream input = stream;
                ByteArrayOutputStream output = new ByteArrayOutputStream(
                        Math.min(maximumBytes, 8192))) {
            byte[] buffer = new byte[8192];
            int observed = 0;
            while (true) {
                int remaining = maximumBytes - observed;
                int requested = remaining >= buffer.length ? buffer.length : remaining + 1;
                int count = input.read(buffer, 0, requested);
                if (count < 0) return output.toByteArray();
                if (count == 0) continue;
                if (observed > maximumBytes - count) {
                    throw new ApiResponseTooLargeException(
                            operationId, attempt, observed + count, maximumBytes);
                }
                output.write(buffer, 0, count);
                observed += count;
            }
        }
    }

    private <T> CompletableFuture<HttpResponse<T>> delayedRetry(RetryCall call, int endpoint, int attempt, long wait,
            IntFunction<HttpResponse.BodyHandler<T>> handlers, ErrorBodyReader<T> errorBodies) {
        return retrySleep.apply(wait)
                .thenCompose(ignored -> sendAttempt(call, endpoint, attempt + 1, handlers, errorBodies));
    }

    private static <T> void transfer(CompletableFuture<T> source, CompletableFuture<T> target) {
        target.whenComplete((ignored, error) -> { if (target.isCancelled()) source.cancel(true); });
        source.whenComplete((value, error) -> {
            Throwable cause = unwrap(error);
            if (cause == null) target.complete(value);
            else if (cause instanceof CancellationException) target.cancel(true);
            else target.completeExceptionally(cause);
        });
    }

    private static Throwable unwrap(Throwable error) {
        if (error == null) return null;
        while ((error instanceof CompletionException) && error.getCause() != null) error = error.getCause();
        return error;
    }

    /** Connection failures, timeouts and interrupted body reads may be retried; programming errors never. */
    private static boolean isRetryableTransport(Throwable error) {
        return error instanceof IOException || error instanceof UncheckedIOException;
    }

    /** 408, 409, 429 and every 5xx, mirroring the TypeScript runtime (425 is never retried). */
    private static boolean isRetryableStatus(int status) {
        return status == 408 || status == 409 || status == 429 || status >= 500;
    }

    /** {@code x-should-retry: true} or {@code false} is the server's verdict and overrides the status policy. */
    private static boolean shouldRetry(int status, HttpHeaders responseHeaders) {
        String verdict = responseHeaders.firstValue("x-should-retry").orElse(null);
        if ("true".equals(verdict)) return true;
        if ("false".equals(verdict)) return false;
        return isRetryableStatus(status);
    }

    private static final long MAXIMUM_BACKOFF_MILLIS = 60_000L;

    /**
     * The wait before the next attempt in milliseconds, or null when no retry should
     * happen. A server asking for longer than maxRetryDelay gets its error surfaced at
     * once rather than an early retry it said would fail; otherwise the wait is the
     * server's own, else an exponential backoff of 500 ms doubling per attempt (at most
     * maxRetryDelay and 60 seconds) with jitter in [50%, 100%] so synchronized clients
     * do not stampede. retryBudget caps the whole call, the time already spent included.
     */
    private Long retryWait(int attempt, HttpHeaders responseHeaders, long startedNanos) {
        // The server's own wait (capability evidence needle).
        Long server = responseHeaders == null ? null : serverRetryDelay(responseHeaders);
        if (server != null && Duration.ofMillis(server).compareTo(options.maxRetryDelay) > 0) return null;
        long ceiling = options.maxRetryDelay.compareTo(Duration.ofMillis(MAXIMUM_BACKOFF_MILLIS)) < 0
                ? options.maxRetryDelay.toMillis() : MAXIMUM_BACKOFF_MILLIS;
        double jitter = 0.5 + Math.min(1.0, Math.max(0.0, retryRandom.getAsDouble())) * 0.5;
        long wait = server != null ? server : (long) (Math.min(ceiling, 500L << Math.min(attempt - 1, 20)) * jitter);
        if (options.retryBudget != null
                && Duration.ofNanos(System.nanoTime() - startedNanos).plusMillis(wait).compareTo(options.retryBudget) > 0)
            return null;
        return wait;
    }

    /**
     * The wait the server asked for in milliseconds, or null: {@code retry-after-ms},
     * then {@code Retry-After} in seconds or as an HTTP date, then the IETF RateLimit
     * reset (the {@code t=} parameter of {@code RateLimit}, or {@code RateLimit-Reset}
     * in seconds). A wait too long for a long saturates, so it still exceeds any
     * maxRetryDelay.
     */
    private static Long serverRetryDelay(HttpHeaders responseHeaders) {
        String milliseconds = responseHeaders.firstValue("retry-after-ms").orElse("").trim();
        if (milliseconds.matches("[0-9]+(\\.[0-9]+)?")) return (long) Double.parseDouble(milliseconds);
        Long retryAfter = parseRetryAfter(responseHeaders.firstValue("retry-after").orElse(null));
        if (retryAfter != null) return retryAfter;
        for (String part : responseHeaders.firstValue("ratelimit").orElse("").split("[;,\\s]")) {
            if (part.matches("t=[0-9]+")) return (long) (Double.parseDouble(part.substring(2)) * 1000.0);
        }
        String reset = responseHeaders.firstValue("ratelimit-reset").orElse("").trim();
        return reset.matches("[0-9]+") ? (long) (Double.parseDouble(reset) * 1000.0) : null;
    }

    /** {@code Retry-After} in milliseconds: delta seconds or an HTTP date (a past one is 0), else null. */
    private static Long parseRetryAfter(String value) {
        if (value == null) return null;
        String trimmed = value.trim();
        if (trimmed.isEmpty()) return null;
        if (trimmed.matches("[0-9]+(\\.[0-9]+)?")) return (long) (Double.parseDouble(trimmed) * 1000.0);
        try {
            long target = ZonedDateTime.parse(trimmed, DateTimeFormatter.RFC_1123_DATE_TIME)
                    .toInstant().toEpochMilli();
            return Math.max(0L, target - System.currentTimeMillis());
        } catch (RuntimeException notADate) { return null; }
    }

    private static ApiException apiException(int status, HttpHeaders responseHeaders, byte[] rawBytes,
            String operationId, int attempts, boolean retryable) {
        String rawBody = new String(rawBytes, StandardCharsets.UTF_8);
        Object body;
        try { body = rawBody.isBlank() ? null : Json.parse(rawBytes); }
        catch (JsonException ignored) { body = rawBody; }
        String requestId = responseHeaders.firstValue("x-request-id")
                .or(() -> responseHeaders.firstValue("request-id")).orElse(null);
        return ApiException.forStatus(status, responseHeaders.map(), body, rawBody, requestId,
                operationId, attempts, retryable);
    }

    private void applyAuthentication(List<Map.Entry<String, String>> query,
            Map<String, String> headers, Map<String, String> cookies,
            List<List<String>> alternatives, String operationId) {
        if (alternatives.isEmpty()) return;
        for (List<String> alternative : alternatives) {
            if (alternative.isEmpty()) return;
            List<Map.Entry<AuthScheme, String>> resolved = new ArrayList<>();
            boolean valid = true;
            for (String name : alternative) {
                AuthScheme scheme = AUTH_SCHEMES.get(name);
                if (scheme == null) { valid = false; break; }
                String value = credential(name, scheme);
                if (value == null && !"mutualTLS".equals(scheme.type)) { valid = false; break; }
                resolved.add(Map.entry(scheme, value == null ? "" : value));
            }
            if (!valid) continue;
            for (Map.Entry<AuthScheme, String> item : resolved) {
                AuthScheme scheme = item.getKey();
                String value = item.getValue();
                if ("apiKey".equals(scheme.type)) {
                    if ("query".equals(scheme.location)) query.add(Map.entry(scheme.name, value));
                    else if ("cookie".equals(scheme.location)) cookies.put(scheme.name, value);
                    else headers.put(scheme.name, value);
                } else if (isBearer(scheme)) {
                    headers.put("Authorization", "Bearer " + value);
                } else if ("http".equals(scheme.type) && "basic".equalsIgnoreCase(scheme.scheme)) {
                    headers.put("Authorization", "Basic " + Base64.getEncoder()
                            .encodeToString(value.getBytes(StandardCharsets.UTF_8)));
                }
            }
            return;
        }
        throw new MissingCredentialsException(operationId,
                "No configured credential satisfies this operation");
    }

    private String credential(String name, AuthScheme scheme) {
        String explicit = options.auth.get(name);
        if (explicit != null) return explicit;
        if ("apiKey".equals(scheme.type)) return options.apiKey;
        if (isBearer(scheme)) return options.accessToken;
        if ("http".equals(scheme.type) && "basic".equalsIgnoreCase(scheme.scheme)
                && options.username != null)
            return options.username + ":" + (options.password == null ? "" : options.password);
        return null;
    }

    private static boolean isBearer(AuthScheme scheme) {
        return "oauth2".equals(scheme.type) || "openIdConnect".equals(scheme.type)
                || ("http".equals(scheme.type) && "bearer".equalsIgnoreCase(scheme.scheme));
    }

    private static void addQuery(List<Map.Entry<String, String>> query, String name,
            Object value, String style, boolean explode) {
        Object plain = value instanceof JsonEncodable encoded ? encoded.toJson() : value;
        if (plain instanceof Collection<?> collection && explode && !"deepObject".equals(style)) {
            for (Object item : collection) query.add(Map.entry(name, toWire(item)));
        } else if (plain instanceof Map<?, ?> map && "deepObject".equals(style)) {
            map.forEach((key, item) -> query.add(Map.entry(name + "[" + toWire(key) + "]", toWire(item))));
        } else if (plain instanceof Map<?, ?> map && explode) {
            // form style, exploded object: each property becomes its own query pair.
            map.forEach((key, item) -> query.add(Map.entry(toWire(key), toWire(item))));
        } else query.add(Map.entry(name, serializeParameter(plain, style, explode)));
    }

    private static String serializeParameter(Object value, String style, boolean explode) {
        Object plain = value instanceof JsonEncodable encoded ? encoded.toJson() : value;
        String separator = "spaceDelimited".equals(style) ? " " : "pipeDelimited".equals(style) ? "|" : ",";
        if (plain instanceof Collection<?> collection) {
            return String.join(separator, collection.stream().map(ApiClient::toWire).toList());
        }
        if (plain instanceof Map<?, ?> map) {
            // RFC 6570: exploded objects serialize as k=v pairs, unexploded ones as
            // the flat k,v,k,v sequence.
            List<String> values = new ArrayList<>();
            map.forEach((key, item) -> {
                if (explode) values.add(toWire(key) + "=" + toWire(item));
                else { values.add(toWire(key)); values.add(toWire(item)); }
            });
            return String.join(separator, values);
        }
        return toWire(plain);
    }

    private static String toWire(Object value) {
        if (value == null) return "";
        if (value instanceof Boolean booleanValue) return booleanValue ? "true" : "false";
        if (value instanceof WireEnum wireEnum) return wireEnum.wireValue();
        return String.valueOf(value);
    }

    private static final char[] HEX = "0123456789ABCDEF".toCharArray();

    /** RFC 3986 percent-encoding: unreserved characters stay, everything else is UTF-8 %XX. */
    private static String percentEncode(String value) {
        byte[] bytes = value.getBytes(StandardCharsets.UTF_8);
        StringBuilder output = new StringBuilder(bytes.length + 16);
        for (byte item : bytes) {
            int ch = item & 0xff;
            boolean unreserved = (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z')
                    || (ch >= '0' && ch <= '9') || ch == '-' || ch == '.' || ch == '_' || ch == '~';
            if (unreserved) output.append((char) ch);
            else output.append('%').append(HEX[ch >> 4]).append(HEX[ch & 0x0f]);
        }
        return output.toString();
    }

    /** Query and cookie component encoding (space is %20, never '+'). */
    private static String encode(String value) { return percentEncode(value); }

    /** Path segment encoding: a single segment, so '/' is encoded as %2F. */
    private static String encodePath(String value) { return percentEncode(value); }

    private static <T> T await(CompletableFuture<T> future) {
        try { return future.join(); }
        catch (CompletionException exception) {
            Throwable cause = unwrap(exception);
            if (cause instanceof RuntimeException runtime) throw runtime;
            // An Error, such as a failed assertion in an onAttempt listener, is never wrapped.
            if (cause instanceof Error fatal) throw fatal;
            throw new ApiTransportException("unknown", 1, cause);
        }
    }

    private record AuthScheme(String type, String name, String location, String scheme) {}
