    /** A successful buffered response with immutable metadata, raw bytes, and its decoded value. */
    public static final class ApiResponse<T> {
        private final int statusCode;
        private final Map<String, List<String>> headers;
        private final String requestId;
        private final byte[] body;
        private final T value;
        public ApiResponse(int statusCode, Map<String, List<String>> headers, byte[] body, T value) {
            this.statusCode = statusCode;
            TreeMap<String, List<String>> normalized = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
            headers.forEach((name, values) -> normalized.put(name, List.copyOf(values)));
            this.headers = Collections.unmodifiableMap(normalized);
            List<String> ids = normalized.get("x-request-id");
            if (ids == null || ids.isEmpty()) ids = normalized.get("request-id");
            this.requestId = ids == null || ids.isEmpty() ? null : ids.get(0);
            this.body = body.clone();
            this.value = value;
        }
        public int statusCode() { return statusCode; }
        public Map<String, List<String>> headers() { return headers; }
        public String requestId() { return requestId; }
        public byte[] body() { return body.clone(); }
        public T value() { return value; }
    }
    private static void captureDeclaredResponseHeaders(ResponseData response, String operation,
            String... names) {
        Objects.requireNonNull(response, "response");
        Objects.requireNonNull(operation, "operation");
        for (String name : names) response.headers().get(name);
    }
    private static void captureDeclaredResponseHeaders(HttpResponse<?> response, String operation,
            String... names) {
        Objects.requireNonNull(response, "response");
        Objects.requireNonNull(operation, "operation");
        for (String name : names) response.headers().allValues(name);
    }
