    /**
     * Root of every failure the client raises. A non-2xx status arrives as the
     * subclass named after it ({@link NotFoundException}, {@link RateLimitException},
     * ...); transport failures, timeouts, oversized responses and missing credentials
     * descend from the same root with {@code statusCode == 0}.
     */
    @SuppressWarnings("serial")
    public static class ApiException extends RuntimeException {
        /** HTTP status, or 0 when no response was received. */
        public final int statusCode;
        public final Map<String, List<String>> headers;
        /** The parsed JSON error body, the raw text when it was not JSON, or null. */
        public final Object body;
        public final String rawBody;
        public final String requestId;
        public final String operationId;
        public final int attempts;
        public final boolean retryable;

        protected ApiException(String message, Throwable cause, int statusCode,
                Map<String, List<String>> headers, Object body, String rawBody, String requestId,
                String operationId, int attempts, boolean retryable) {
            super(message, cause);
            this.statusCode = statusCode;
            this.headers = Collections.unmodifiableMap(new LinkedHashMap<>(headers));
            this.body = body;
            this.rawBody = rawBody;
            this.requestId = requestId;
            this.operationId = operationId;
            this.attempts = attempts;
            this.retryable = retryable;
        }

        ApiException(int statusCode, Map<String, List<String>> headers, Object body,
                String rawBody, String requestId, String operationId, int attempts, boolean retryable) {
            this(statusMessage(statusCode, body, operationId), null, statusCode, headers, body, rawBody,
                    requestId, operationId, attempts, retryable);
        }

        /** The peer's own message when the error body carries one, else the status line. */
        static String statusMessage(int statusCode, Object body, String operationId) {
            String message = "HTTP " + statusCode + " for " + operationId;
            if (body instanceof Map<?, ?> map) {
                for (String key : new String[] {"message", "detail", "title", "error", "error_description"}) {
                    Object value = map.get(key);
                    if (value instanceof String text && !text.isBlank()) return message + ": " + text;
                    if (value instanceof Map<?, ?> nested && nested.get("message") instanceof String text
                            && !text.isBlank()) return message + ": " + text;
                }
            }
            return message;
        }

        static ApiException forStatus(int statusCode, Map<String, List<String>> headers, Object body,
                String rawBody, String requestId, String operationId, int attempts, boolean retryable) {
            switch (statusCode) {
                case 400: return new BadRequestException(headers, body, rawBody, requestId, operationId, attempts, retryable);
                case 401: return new AuthenticationException(headers, body, rawBody, requestId, operationId, attempts, retryable);
                case 403: return new PermissionDeniedException(headers, body, rawBody, requestId, operationId, attempts, retryable);
                case 404: return new NotFoundException(headers, body, rawBody, requestId, operationId, attempts, retryable);
                case 409: return new ConflictException(headers, body, rawBody, requestId, operationId, attempts, retryable);
                case 422: return new UnprocessableEntityException(headers, body, rawBody, requestId, operationId, attempts, retryable);
                case 429: return new RateLimitException(headers, body, rawBody, requestId, operationId, attempts, retryable);
                default:
                    if (statusCode >= 500) {
                        return new InternalServerException(statusCode, headers, body, rawBody, requestId,
                                operationId, attempts, retryable);
                    }
                    return new ApiException(statusCode, headers, body, rawBody, requestId, operationId, attempts, retryable);
            }
        }
    }

